"""Deli Counter 0.279.0: a supermarket's ceiling rows bake to the next lamp along -- each sales-floor fluorescent row
carries `bake_reach`, its lamp spacing, for Lux 0.80.0's bake-only range (the walker: "far too dark in teh super
market"; the factory's docs/findings/black_gondola_ends/).

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * lights.py -- edited.
  * tests/test_bake_reach.py -- new.
  * VERSION 0.278.0 -> 0.279.0, CHANGELOG.

Generated by `patches/dc_bake_reach/gen_dc_bake_reach.py` from a proven clone. After it: `build.py --all`,
`nav_gate.py --all`, the suite.

    python patches/patch_dc_bake_reach.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "deli_counter"
PINS = {'lights.py': '9da0557fee944ada'}
EDITS = {'lights.py': [('lines 1575-1575', '                         storefronts=None, residence=False, landings=None):\n', '                         storefronts=None, residence=False, landings=None,\n                         bake_reach_rooms=None):\n'), ('lines 1763-1764', "                    room_reach = max(room_reach, reach)\n        # THE STORE'S LIGHT ON THE PAVEMENT (0.156.0): a room whose row\n", '                    room_reach = max(room_reach, reach)\n            # A ROW THAT BAKES TO THE NEXT LAMP (0.279.0): a room in\n            # `bake_reach_rooms` -- a supermarket\'s selling floor -- stamps its\n            # row\'s spacing as `bake_reach`, and Lux (>= 0.80.0) bakes the\n            # lamp to the floor under the next one along while its live\n            # range, the per-mesh claim, stays the drop rule. Measured on the\n            # walker\'s level: the store\'s frame 38.5 -> 61.5 mean at x 1.6\n            # range (the factory\'s docs/findings/black_gondola_ends/).\n            if (not moody and not home and sp > 0.0\n                    and r.get("id") in (bake_reach_rooms or ())):\n                anchors[-1]["bake_reach"] = round(float(sp), 3)\n        # THE STORE\'S LIGHT ON THE PAVEMENT (0.156.0): a room whose row\n'), ('lines 1890-1891', '\ndef build_light_manifest(building_id, rooms, openings, story_height,\n', '\ndef _bake_reach_rooms(rooms, business):\n    """The rooms whose fluorescent rows bake to the next lamp (0.279.0): a\n    supermarket\'s selling floor (`level_design.is_supermarket_floor`), the\n    walker\'s "far too dark in the super market"."""\n    if not business:\n        return set()\n    import level_design\n    return {r.get("id") for r in rooms or () if level_design.is_supermarket_floor(r, business)}\n\n\ndef build_light_manifest(building_id, rooms, openings, story_height,\n'), ('lines 1913-1913', '                                   landings=landings)\n', '                                   landings=landings,\n                                   bake_reach_rooms=_bake_reach_rooms(rooms, business))\n')]}
REPLACED = {}
NEW_FILES = {'tests/test_bake_reach.py': '"""A supermarket\'s ceiling rows bake to the next lamp along (0.279.0).\n\nThe walker, 2026-10-26: "far too dark in teh super market". The supermarket\'s lamps are baked statics whose range is\nthe drop rule, written for the realtime claim each lamp makes on every mesh it reaches; re-baked with the range x 1.6\nthe store\'s frame rose 38.5 -> 61.5 mean (the factory\'s docs/findings/black_gondola_ends/). Lux (>= 0.80.0) lends a\nstatic lamp a longer range only while a lightmap bakes, derived from a row\'s `bake_reach`. A supermarket\'s selling\nfloor stamps its rows\' spacing as that; no other room carries it.\n\nFAILS ON 0.278.0: no row carries `bake_reach`, and `derive_light_anchors` takes no `bake_reach_rooms`.\n"""\nimport json\nimport os\n\nimport pytest\n\nimport lights\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nBUILD = os.path.join(HERE, "build")\n\n\ndef _cap(_story):\n    return 0.3\n\n\nSALES = {"id": "sales_floor", "story": 0, "center": [0.0, -4.0, 0.0],\n         "bounds": [-17.0, -15.0, 17.0, 7.0], "role": "public_entry"}\nBACK = {"id": "stockroom", "story": 0, "center": [0.0, 10.0, 0.0],\n        "bounds": [-17.0, 7.0, 17.0, 13.0]}\n\n\ndef _rows(rooms, **kw):\n    out = {}\n    for a in lights.derive_light_anchors(rooms, [], 4.4, cap_thick=_cap, wall_thick=0.3, **kw):\n        if a["type"] in ("fluorescent", "pendant", "dome"):\n            out.setdefault(a["room"], []).append(a)\n    return out\n\n\ndef test_a_named_rooms_rows_carry_their_spacing_and_no_other_rooms_do():\n    rows = _rows([SALES, BACK], bake_reach_rooms={"sales_floor"})\n    assert rows["sales_floor"]\n    for a in rows["sales_floor"]:\n        assert a["type"] == "fluorescent"\n        assert a["bake_reach"] == round(a["row"]["spacing"], 3) > 0.0, a\n    for a in rows["stockroom"]:\n        assert "bake_reach" not in a, a\n\n\ndef test_without_a_named_room_every_row_is_as_before():\n    """The control: the same rooms with no `bake_reach_rooms` are 0.278.0\'s anchors exactly."""\n    plain = _rows([SALES, BACK])\n    named = _rows([SALES, BACK], bake_reach_rooms={"sales_floor"})\n    for room, got in named.items():\n        assert [{k: v for k, v in a.items() if k != "bake_reach"} for a in got] == plain[room]\n    assert not any("bake_reach" in a for got in plain.values() for a in got)\n\n\ndef test_the_supermarket_floor_is_the_named_room():\n    got = lights._bake_reach_rooms([SALES, BACK], "supermarket_a01")\n    assert got == {"sales_floor"}\n    assert lights._bake_reach_rooms([SALES, BACK], "convenience_store_a01") == set()\n    assert lights._bake_reach_rooms([SALES, BACK], None) == set()\n\n\n@pytest.mark.parametrize("name", ["supermarket_a01", "supermarket_a02", "supermarket_a03"])\ndef test_every_built_supermarkets_sales_floor_rows_carry_it(name):\n    path = os.path.join(BUILD, name + ".lights.json")\n    if not os.path.exists(path):\n        pytest.skip("%s is not built" % name)\n    with open(path, encoding="utf-8") as fh:\n        anchors = json.load(fh)["anchors"]\n    sales = [a for a in anchors if a.get("type") == "fluorescent" and a.get("room") == "sales_floor"]\n    others = [a for a in anchors if a.get("type") == "fluorescent" and a.get("room") != "sales_floor"]\n    assert sales, name\n    assert all(a.get("bake_reach", 0.0) > 0.0 for a in sales), name\n    assert not any("bake_reach" in a for a in others), name\n'}
CHANGELOG = '## [0.279.0] - a supermarket\'s ceiling rows bake to the next lamp along\n\nThe walker, 2026-10-26: "far too dark in teh super market". Measured on the walker\'s level (the factory\'s\ndocs/findings/black_gondola_ends/):\n\n- The supermarket\'s lamps are baked statics whose range is the drop rule. That rule was written for the realtime\n  claim each lamp makes on every mesh it reaches.\n- Re-baked with the range x 1.6, the store\'s frame rose 38.5 -> 61.5 mean, and the gondolas\' black ends lifted.\n\nLux 0.80.0 lends a static lamp a longer range only while a lightmap bakes. It derives that range as\n`hypot(drop, bake_reach) + 0.75` from a row\'s `bake_reach`.\n\n### Added\n- **`bake_reach`** on the fluorescent rows of a room in `derive_light_anchors`\' new `bake_reach_rooms`: the row\'s\n  lamp spacing, so the bake reaches the floor under the next lamp along. Lux makes 7.61 m of it in supermarket_a01\n  (drop 4.1, spacing 5.5), x 1.57 its live 4.85.\n- **`_bake_reach_rooms(rooms, business)`**: a supermarket\'s selling floor (`level_design.is_supermarket_floor`). In\n  the library that is the three supermarkets\' `sales_floor` rows (spacing 5.5, 5.5 and 5.0 m). Every other anchor is\n  byte-identical to 0.278.0\'s. Zoo 1.134.0 carries it to the lamps\' markers.\n\n### Tests\n- `tests/test_bake_reach.py` (all 6 fail on 0.278.0):\n  - a named room\'s rows carry their spacing, and no other room\'s do;\n  - without a named room every row is 0.278.0\'s anchor exactly (the control);\n  - the supermarket floor is the named room, and a convenience store\'s is not;\n  - every built supermarket\'s sales-floor rows carry it.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.278.0', 'Deli Counter 0.279.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
